INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Komponententest immer einzelne Module prüft?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf Einzelkomponenten"}, {"text": "Nein", "correct": false, "because": "Nicht auf Zusammenarbeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Module zusammen prüfe?', 3, '[{"text": "Schnittstellenfunktion", "correct": true, "because": "Testet Zusammenspiel"}, {"text": "Einzelne Logik", "correct": false, "because": "Komponententest"}, {"text": "Hardwareleistung", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte prüfe ich, wenn Komponenten kombiniert werden?', 5, '[{"text": "Datenfluss", "correct": true, "because": "Zwischen Modulen"}, {"text": "Interaktion", "correct": true, "because": "Schnittstellen testen"}, {"text": "Kompatibilität", "correct": true, "because": "Zusammenarbeit"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Er testet Schnittstellen. b) Er prüft nur einzelne Funktionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist Komponententest"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Module zusammen teste?', 4, '[{"text": "Schnittstellen", "correct": false, "because": "Kern der Prüfung"}, {"text": "Datenübergabe", "correct": false, "because": "Entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein solcher Test immer manuell ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um zwei Module zu prüfen?', 3, '[{"text": "Mocking", "correct": true, "because": "Simuliert Abhängigkeiten"}, {"text": "Unit-Test", "correct": false, "because": "Einzelkomponenten"}, {"text": "Design-Tool", "correct": false, "because": "Kein Testwerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Testen von Modulgruppen?', 5, '[{"text": "Fehlerlokalisierung", "correct": true, "because": "Schnittstellenprobleme"}, {"text": "Systemstabilität", "correct": true, "because": "Zusammenspiel gesichert"}, {"text": "Integration prüfen", "correct": true, "because": "Funktion als Ganzes"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Testzeit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Schnittstellen geprüft werden und b) es ohne Vorbereitung geht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vorbereitung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Module zusammen zu testen?', 4, '[{"text": "Testfälle", "correct": false, "because": "Definieren Szenarien"}, {"text": "Schnittstellen", "correct": false, "because": "Kern der Prüfung"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Testet man damit immer das ganze System?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Teile"}, {"text": "Ja", "correct": false, "because": "Systemtest ist anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen beim Testen von Komponentengruppen?', 4, '[{"text": "Top-Down", "correct": true, "because": "Von oben nach unten"}, {"text": "Bottom-Up", "correct": true, "because": "Von unten nach oben"}, {"text": "Zufällige Auswahl", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein solcher Test immer automatisiert ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Manuell möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich Module integriere?', 3, '[{"text": "Funktionsprüfung", "correct": true, "because": "Zusammenspiel testen"}, {"text": "Einzeloptimierung", "correct": false, "because": "Unit-Test"}, {"text": "Designverbesserung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Er prüft Datenfluss. b) Er testet Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Mocking beim Testen?', 4, '[{"text": "Abhängigkeiten simulieren", "correct": true, "because": "Isoliert Module"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht Zweck"}, {"text": "Design anpassen", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein solcher Test vor dem Unit-Test kommt?', 2, '[{"text": "Nein", "correct": true, "because": "Nach Unit-Test"}, {"text": "Ja", "correct": false, "because": "Unit-Test zuerst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das Testen von Modulen nützlich?', 5, '[{"text": "Schnittstellenprüfung", "correct": true, "because": "Zusammenspiel sicher"}, {"text": "Fehlerfrüherkennung", "correct": true, "because": "Vor Systemtest"}, {"text": "Systemintegration", "correct": true, "because": "Modulverknüpfung"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein solcher Test dasselbe wie ein Systemtest?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Teile, nicht Gesamt"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum Testen von Modulgruppen?', 4, '[{"text": "API mit Datenbank", "correct": true, "because": "Schnittstellenprüfung"}, {"text": "Einzelfunktion", "correct": false, "because": "Unit-Test"}, {"text": "Webdesign", "correct": false, "because": "Anderer Fokus"}]');
